document.addEventListener('DOMContentLoaded',()=>{if(!window.cvData||!window.Utils){console.error('❌ Error Crítico: cvData o Utils no cargaron.');return;}const cv=window.cvData;const labels=cv.labels||{};const currentYear=new Date().getFullYear();const getSectionTitle=(idx,fallback)=>{const sections=cv.sections||[];const s=sections[idx]||null;if(!s)return fallback||'';const raw=s.title||'';const cleaned=window.Utils.stripHtmlToText?window.Utils.stripHtmlToText(raw):raw .replace(/<br\s*\/?>/gi,' ').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();return `${s.index} / ${cleaned.toUpperCase()}`;};const coverSrc=window.Utils.getSmartPath('cover_art','PORTFOLIO');const backSrc=window.Utils.getSmartPath('cover_art','PORTFOLIO');const container=document.getElementById('magazine-target');if(!container){console.error('❌ Error: No se encontró #magazine-target');return;}let totalPageCount=0;const addPage=(hasFooter=true)=>{if(hasFooter)totalPageCount++;const sec=document.createElement('section');sec.className='magazine-page';const footerHtml=hasFooter?`<div class="mag-footer">
           <span>TARQUITET // ${currentYear}</span>
           <span>PAG. ${totalPageCount.toString().padStart(2, '0')}</span>
         </div>`:'';sec.innerHTML=`<div class="page-content" style="${hasFooter ? '' : 'height:100%'}"></div>${footerHtml}`;container.appendChild(sec);return sec.querySelector('.page-content');};const getIcon=(type,key)=>{const t=(key||'').toLowerCase();if(type==='art'){if(t.includes('sketch'))return '<i data-lucide="pencil"></i>';if(t.includes('ilustracion'))return '<i data-lucide="palette"></i>';return '<i data-lucide="image"></i>';}const soft=cv.software.find((s)=>s.name.toLowerCase().includes(t.split('/')[0]));if(!soft)return '<i data-lucide="code-2"></i>';return soft.iconType==='lucide'?`<i data-lucide="${soft.iconName}"></i>`:`<i class="${soft.iconClass}"></i>`;};const renderSection=(items,label,groupKey)=>{if(!items||!items.length)return;const groups={};items.forEach((p)=>{const keys=p[groupKey];const k=keys&&keys.length>0?keys[0]:'General';if(!groups[k])groups[k]=[];groups[k].push(p);});let page=addPage(true);let count=0;let newSec=true;for(const[subCat,elements]of Object.entries(groups)){if(newSec){page.innerHTML+=`<div class="section-label">${label}</div>`;newSec=false;}const iconType=groupKey==='tags'?'art':'tool';const ribbonHtml=`<div class="sub-ribbon">${getIcon(iconType, subCat)}<span> ${subCat.toUpperCase()}</span></div>`;page.innerHTML+=ribbonHtml;elements.forEach((item)=>{if(count>=4){page=addPage(true);page.innerHTML+=`<div class="section-label">${label} (CONT.)</div>`+ribbonHtml;count=0;}const category=groupKey==='tags'?'ART':item.category;const imgSrc=window.Utils.getSmartPath(item.image||item.fileName,category);const toolsSafe=item.tools||[];const meta=groupKey==='tags'?`// ${item.date || ''}`:`// ${toolsSafe.join(' / ')}`;page.innerHTML+=`
            <article class="project-container">
                <div class="img-block">
                    <img src="${imgSrc}" alt="${item.title}" onerror="window.Utils.handleImgError(this)">
                </div>
                <div class="info-block">
                    <div class="p-title-ribbon">${item.title}</div>
                    <div class="info-card">
                        <div class="p-meta">${meta}</div>
                        <p class="p-desc">${item.desc}</p>
                    </div>
                </div>
            </article>`;count++;});}};const p1=addPage(false);const roleText=cv.basics.role?cv.basics.role.toUpperCase():'MULTIMEDIA ENGINEER';p1.innerHTML=`
    <div class="cover-layout">
      <div class="cover-vertical">> TARQUITET</div>
      
      <div class="cover-main">
        <div class="cover-img">
            <img src="${coverSrc}" alt="Cover" style="width:100%; height:100%; object-fit:cover;" onerror="window.Utils.handleImgError(this)">
            
            <div class="mag-overlay">
                <div style="text-align:right; font-family:var(--f-code); color:#fff; font-size:9pt; opacity:0.8;">
                    ISSUE NO. 01 // ${currentYear}
                </div>

                <div>
                    <div class="mag-headline">THE<br>ARCHITECT</div>
                    <div class="mag-sublines">> ${roleText}</div>
                    
                    <div class="barcode-strip">
                        <div class="css-barcode"></div>
                        <div style="text-align:right; color:#fff; font-family:var(--f-code); font-size:8pt;">
                            $ PRICELESS<br>EDITION: GLOBAL
                        </div>
                    </div>
                </div>
            </div>
        </div>

        <div style="border-top:4px solid var(--text); padding-top:10px; display:flex; justify-content:space-between; align-items:flex-end;">
          <div>
             <div style="font-weight:900; font-size:14pt; line-height:1.1;">${cv.basics.name.replace('<br>', ' ')}</div>
             <div style="font-family:var(--f-code); font-size:9pt; margin-top:4px; opacity:0.7;">PORTFOLIO DOCUMENT</div>
          </div>
          <div style="text-align:right;">
             <div style="background:var(--text); color:var(--bg); padding:4px 8px; font-weight:bold; font-size:9pt;">
                CONFIDENTIAL
             </div>
          </div>
        </div>
      </div>
    </div>`;const port=(window.mainPortfolio||[]).filter((p)=>p.category!=='VIDEO'&&p.context!=='UNIVERSITY');const gallery=window.galleryData||[];renderSection(port.filter((p)=>p.category==='DEV'),getSectionTitle(0,'01 / DEVELOPMENT'),'tools',);renderSection(port.filter((p)=>p.category==='DESIGN'),getSectionTitle(2,'02 / DESIGN & UI'),'tools',);renderSection(gallery,getSectionTitle(3,'04 / VISUAL ARTS'),'tags');const pLast=addPage(false);const allowedNetworks=['linkedin','github','@'];const professionalContacts=cv.contact.filter((c)=>{const combined=(c.text+c.link).toLowerCase();return allowedNetworks.some((keyword)=>combined.includes(keyword));});const linksHtml=professionalContacts .map((c)=>{let icon='>';const txt=c.text.toLowerCase();if(txt.includes('@'))icon='@';if(c.link.includes('linkedin'))icon='IN';if(c.link.includes('github'))icon='GIT';const isLink=c.link&&c.link!=='-';const tag=isLink?'a':'div';const href=isLink?`href="${c.link}" target="_blank"`:`onclick="window.Utils.copyText('${c.text}', this)"`;const cursor=isLink?'pointer':'copy';return `
        <${tag} ${href} style="display:flex; justify-content:space-between; align-items:center; font-family:var(--f-code); font-size:10pt; color:var(--bg); text-decoration:none; border-bottom:1px solid rgba(242,240,233,0.2); padding:12px 0; cursor:${cursor}; transition:0.2s;">
            <span style="opacity:0.9; font-weight:bold;">${icon} // ${c.text.toUpperCase()}</span>
            <span style="opacity:0.5;">↗</span>
        </${tag}>`;}).join('');pLast.innerHTML=`
    <div style="display:flex; flex-direction:column; height:100%; position:relative;">
        
        <div style="flex:1; border:2px solid var(--text); overflow:hidden; position:relative; background:#000;">
            <img src="${backSrc}" style="width:100%; height:100%; object-fit:cover; filter: grayscale(100%) contrast(1.1);" onerror="window.Utils.handleImgError(this)">
            
            <div style="position:absolute; bottom:20px; left:20px; color:#fff; font-family:var(--f-code); font-size:8pt; opacity:0.8;">
                /// SYSTEM SHUTDOWN<br>
                /// EXECUTION COMPLETE
            </div>
            
            <div style="position:absolute; bottom:20px; right:20px; background:var(--accent); color:#fff; padding:5px 10px; font-family:var(--f-code); font-size:8pt; font-weight:bold;">
                ● AVAILABLE FOR HIRE
            </div>
        </div>

        <div class="back-thank-you" style="background:var(--box-dark); padding:40px 30px; margin-top:-20px; position:relative; z-index:10; border:none; border-left:4px solid var(--accent);">
            
            <div style="display:flex; justify-content:space-between; align-items:flex-end; margin-bottom:30px;">
                <h1 class="back-title" style="font-size:45pt; margin:0; line-height:0.9;">LET'S<br>TALK.</h1>
                <div style="text-align:right; font-family:var(--f-code); color:var(--bg); opacity:0.5; font-size:8pt;">
                    David Josué Pinto Gómez<br>
                    Ingeniero Multimedia
                </div>
            </div>

            <div style="display:flex; flex-direction:column; gap:0px; margin-bottom:40px;">
                ${linksHtml}
            </div>

            <div style="border-top:2px solid var(--accent); padding-top:15px; display:flex; justify-content:space-between; font-family:var(--f-code); font-size:7pt; color:var(--bg); opacity:0.6;">
                <div>
                    TARQUITET.COM // PORTFOLIO_V2<br>
                    BOGOTÁ, COLOMBIA
                </div>
                <div style="text-align:right;">
                    © ${currentYear} ALL RIGHTS RESERVED.<br>
                    END OF FILE.
                </div>
            </div>

        </div>
    </div>`;if(window.Utils&&window.Utils.initIcons)window.Utils.initIcons();document.body.classList.add('pdf-ready');});